'use strict';

/**
* Compute a moving arithmetic mean and unbiased sample variance incrementally.
*
* @module @stdlib/stats/incr/nanmmeanvar
*
* @example
* var incrnanmmeanvar = require( '@stdlib/stats/incr/nanmmeanvar' );
*
* var accumulator = incrnanmmeanvar( 3 );
*
* var v = accumulator();
* // returns null
*
* v = accumulator( 2.0 );
* // returns [ 2.0, 0.0 ]
*
* v = accumulator( NaN );
* // returns [ 2.0, 0.0 ]  // NaN skipped
*
* v = accumulator( 4.0 );
* // returns [ 3.0, 2.0 ]
*
* v = accumulator();
* // returns [ 3.0, 2.0 ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
